main.script:
/* Online-session guide (gd-): camera view toggle + redraw, tickable checklist (saved in this browser),
   Zoom sequence and safety highlight entrances, scroll-linked countdown timeline, print helpers.
   Without JS the page is complete: both camera views show, checkboxes still tick, the timeline is fully drawn. */
(function () {
  'use strict';
  var KEY = 'tre-sg-guide-checklist-v1';
  function $(s, c) { return (c || document).querySelector(s); }
  function $$(s, c) { return Array.prototype.slice.call((c || document).querySelectorAll(s)); }
  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }

  function init() {
    var root = $('.gd'); if (!root) return;
    var L = window.TRELayer || {};
    var R = typeof L.reduced === 'boolean' ? L.reduced : !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
    function seeOnce(el, cb, threshold) {
      if (!el) return;
      if (L.onVisible) L.onVisible(el, function (en, isIn) { if (isIn) cb(); }, { once: true, threshold: threshold || 0.25 });
      else cb();
    }
    $$('.gd-view', root).forEach(function (p) { p.classList.add('gd-snap'); });
    if (!R) root.classList.add('gd-armed');
    views(root, R, seeOnce);
    checklist(root);
    if (!R) {
      var safe = $('.gd-safe', root); seeOnce(safe, function () { safe.classList.add('is-in'); }, 0.35);
      var z = $('.gd-zsteps', root); if (z) { z.classList.add('is-armed'); seeOnce(z, function () { z.classList.add('is-in'); }, 0.3); }
    }
    countdown(root, R);
    printing(root);
  }

  /* ---- camera views: tablist (Left/Right/Home/End), cross-fade, redraw the lines of the view that opens ---- */
  function views(root, R, seeOnce) {
    var sw = $('.gd-switch', root), wrap = $('.gd-views', root); if (!sw || !wrap) return;
    var tabs = $$('.gd-tab', sw), panels = $$('.gd-view', wrap), cur = 0, seen = 0;
    sw.hidden = false; wrap.classList.add('is-tabbed');
    function apply(i) {
      cur = i;
      tabs.forEach(function (t, k) { t.setAttribute('aria-selected', k === i ? 'true' : 'false'); t.tabIndex = k === i ? 0 : -1; });
      panels.forEach(function (p, k) { p.classList.toggle('is-active', k === i); if (k === i) p.removeAttribute('inert'); else p.setAttribute('inert', ''); });
      sw.setAttribute('data-active', String(i));
    }
    function redraw(p) {
      p.classList.add('gd-snap'); p.classList.remove('is-drawn'); void p.offsetWidth; p.classList.remove('gd-snap'); p.classList.add('is-drawn');
      if (R || !seen || performance.now() - seen < 1900) return;          // first entrance still drawing (TRELayer.draw)
      var paths = $$('[data-draw]', p), t0 = performance.now();
      paths.forEach(function (el) { el.style.setProperty('--p', 0); });
      requestAnimationFrame(function step(now) {
        var busy = false;
        paths.forEach(function (el) {
          var d = parseFloat(el.getAttribute('data-gd-delay')) || 0, dur = parseFloat(el.getAttribute('data-draw-dur')) || 1200;
          var k = clamp((now - t0 - d) / dur, 0, 1); if (k < 1) busy = true;
          el.style.setProperty('--p', (1 - Math.pow(1 - k, 3)).toFixed(4));
        });
        if (busy) requestAnimationFrame(step);
      });
    }
    function select(i, focus) {
      if (i !== cur) { apply(i); redraw(panels[i]); }
      if (focus) tabs[i].focus();
    }
    tabs.forEach(function (t, k) { t.addEventListener('click', function () { select(k, false); }); });
    sw.addEventListener('keydown', function (e) {
      var n = tabs.length, k = null;
      if (e.key === 'ArrowRight') k = (cur + 1) % n; else if (e.key === 'ArrowLeft') k = (cur + n - 1) % n;
      else if (e.key === 'Home') k = 0; else if (e.key === 'End') k = n - 1;
      if (k === null) return;
      e.preventDefault(); select(k, true);
    });
    apply(0);
    void wrap.offsetWidth;
    panels.forEach(function (p) { p.classList.remove('gd-snap'); });
    if (R) { panels.forEach(function (p) { p.classList.add('is-drawn'); }); return; }
    seeOnce(wrap, function () { seen = performance.now(); panels[cur].classList.add('is-drawn'); }, 0.3);
  }

  /* ---- checklist: ticks + progress line, remembered in this browser only (works without storage) ---- */
  function checklist(root) {
    var list = $('.gd-check', root); if (!list) return;
    var boxes = $$('.gd-cb', list), prog = $('.gd-progress', root), num = $('[data-gd-count]', root),
        fill = $('.gd-fill', root), bar = $('.gd-track', root), clear = $('.gd-clear', root), saved = [];
    try { saved = JSON.parse(window.localStorage.getItem(KEY) || '[]'); } catch (e) { saved = []; }
    if (!Array.isArray(saved)) saved = [];
    list.classList.add('gd-snap');
    boxes.forEach(function (b) { if (saved.indexOf(b.getAttribute('data-gd-item')) > -1) b.checked = true; });
    function update(save) {
      var on = boxes.filter(function (b) { return b.checked; }), n = on.length;
      if (num) num.textContent = String(n);
      if (fill) fill.style.setProperty('--k', (n / boxes.length).toFixed(3));
      if (bar) bar.setAttribute('aria-valuenow', String(n));
      if (prog) prog.classList.toggle('is-full', n === boxes.length);
      if (clear) clear.hidden = n === 0;
      if (save) { try { window.localStorage.setItem(KEY, JSON.stringify(on.map(function (b) { return b.getAttribute('data-gd-item'); }))); } catch (e) {} }
    }
    list.addEventListener('change', function (e) { if (e.target && e.target.classList && e.target.classList.contains('gd-cb')) update(true); });
    if (clear) clear.addEventListener('click', function () { boxes.forEach(function (b) { b.checked = false; }); update(true); if (boxes[0]) boxes[0].focus(); });
    if (prog) prog.hidden = false;
    update(false);
    void list.offsetWidth; list.classList.remove('gd-snap');
  }

  /* ---- on the day: the line fills to the reading position, steps light as they pass, the clock counts the last quarter down ---- */
  function countdown(root, R) {
    var sec = $('.gd-day', root), wrap = $('.gd-tl-wrap', root); if (!sec || !wrap || R) return;
    var items = $$('.gd-tl li', wrap), end = $('.gd-tl-end', wrap), fill = $('.gd-tl-fill', wrap),
        hand = $('.gd-ck-hand', sec), wedge = $('.gd-ck-wedge', sec), raf = 0, lastA = null;
    sec.classList.add('gd-live');
    function clock(p) {
      var a = -90 + 90 * p; if (lastA !== null && Math.abs(a - lastA) < 0.05) return; lastA = a;
      if (hand) hand.setAttribute('transform', 'rotate(' + a.toFixed(2) + ' 100 100)');
      if (wedge) {
        var rad = a * Math.PI / 180, x = 100 + 84 * Math.sin(rad), y = 100 - 84 * Math.cos(rad);
        wedge.setAttribute('d', p > 0.998 ? 'M100 100Z' : 'M100 100L' + x.toFixed(2) + ' ' + y.toFixed(2) + 'A84 84 0 0 1 100 16Z');
      }
    }
    function paint() {
      raf = 0;
      var vh = window.innerHeight || 800, r = wrap.getBoundingClientRect();
      if (r.bottom < -vh || r.top > vh * 2) return;
      var y = vh * 0.62 - r.top, p = clamp((y - 29) / Math.max(1, r.height - 40), 0, 1);
      if (fill) fill.style.setProperty('--t', p.toFixed(4));
      items.forEach(function (li) { li.classList.toggle('on', li.offsetTop + 29 <= y); });
      if (end) end.classList.toggle('on', end.offsetTop + 30 <= y);
      clock(p);
    }
    function queue() { if (!raf) raf = requestAnimationFrame(paint); }
    window.addEventListener('scroll', queue, { passive: true });
    window.addEventListener('resize', queue, { passive: true });
    paint();
  }

  /* ---- print: every answer open on paper, restored afterwards ---- */
  function printing(root) {
    var opened = [];
    window.addEventListener('beforeprint', function () {
      opened = $$('.gd-qa details', root).filter(function (d) { return !d.open; });
      opened.forEach(function (d) { d.open = true; });
    });
    window.addEventListener('afterprint', function () { opened.forEach(function (d) { d.open = false; }); opened = []; });
  }

  document.addEventListener('DOMContentLoaded', function () { setTimeout(init, 0); });
})();
